def transform(grid):
    # Encode horizontal runs by color as one cell each, grouped by color.
    counts = {}
    for row in grid:
        seen = set()
        prev = None
        for value in row:
            if value != prev:
                if value not in (0,):
                    counts[value] = counts.get(value, 0) + 1
            prev = value
    cells = [color for color in sorted(counts) for _ in range(counts[color])]
    if not cells:
        return [[0]]
    width = int(len(cells) ** 0.5)
    while width * width < len(cells):
        width += 1
    height = (len(cells) + width - 1) // width
    cells += [0] * (width * height - len(cells))
    return [cells[i*width:(i+1)*width] for i in range(height)]
